import{_ as e,o,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Página de configurações","description":"","frontmatter":{"title":"Página de configurações"},"headers":[],"relativePath":"geral/configuracoes.md","filePath":"geral/configuracoes.md"}'),d={name:"geral/configuracoes.md"};function i(s,a,n,c,l,u){return o(),r("div",null,a[0]||(a[0]=[t('<h1 id="pagina-de-configuracoes" tabindex="-1">Página de configurações <a class="header-anchor" href="#pagina-de-configuracoes" aria-label="Permalink to &quot;Página de configurações&quot;">​</a></h1><p>É onde ficam todas as funcionalidades do eploc, com seus interruptores e opções, além dos backups, das novidades e dos termos de uso.</p><h2 id="como-abrir" tabindex="-1">Como abrir <a class="header-anchor" href="#como-abrir" aria-label="Permalink to &quot;Como abrir&quot;">​</a></h2><ul><li>Pelo botão <strong>Configurações</strong> do <a href="./popup">popup</a>; ou</li><li>clicando com o botão direito no ícone do eploc e escolhendo <strong>Opções</strong>; ou</li><li>automaticamente, logo após a instalação.</li></ul><h2 id="organizacao" tabindex="-1">Organização <a class="header-anchor" href="#organizacao" aria-label="Permalink to &quot;Organização&quot;">​</a></h2><p>A barra lateral traz:</p><table tabindex="0"><thead><tr><th>Aba</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Ajustes gerais e Backup</td><td><a href="./aparencia">Aparência e efeitos visuais</a>, <a href="./backup-arquivo">backup em arquivo</a> e <a href="./backup-google-drive">backup no Google Drive</a>.</td></tr><tr><td>eproc</td><td>Funcionalidades do eproc, agrupadas por tema (Menu superior, Painel do processo, Eventos, Árvore e minuta, Pesquisa e filtros, Relatórios, Destaques e lembretes, E-mail, Monitoramento, Migração PJe).</td></tr><tr><td>RUPE, SEI, TJMG</td><td>Funcionalidades de cada sistema.</td></tr><tr><td>Novidades</td><td>O que mudou em cada versão, com busca e filtro por sistema. As versões que você ainda não viu aparecem destacadas e abertas. O nome de cada funcionalidade leva ao card dela.</td></tr><tr><td>Sobre</td><td>Versão instalada, termos de uso, links para o site e o suporte.</td></tr></tbody></table><h2 id="o-card-de-cada-funcionalidade" tabindex="-1">O card de cada funcionalidade <a class="header-anchor" href="#o-card-de-cada-funcionalidade" aria-label="Permalink to &quot;O card de cada funcionalidade&quot;">​</a></h2><p>Cada funcionalidade tem um card com:</p><ul><li>nome e descrição;</li><li>interruptor para ligar e desligar;</li><li>as opções da funcionalidade, quando houver (algumas só aparecem conforme outra opção);</li><li>botão do gerenciador de dados, quando houver (por exemplo, <strong>Gerenciar contatos salvos</strong>);</li><li>vídeo de demonstração, para as funcionalidades que têm: passe o mouse sobre o card para vê-lo ao lado.</li></ul><p>As mudanças são salvas na hora e valem nas páginas abertas sem precisar recarregá-las.</p><h2 id="buscar-um-ajuste" tabindex="-1">Buscar um ajuste <a class="header-anchor" href="#buscar-um-ajuste" aria-label="Permalink to &quot;Buscar um ajuste&quot;">​</a></h2><p>O campo <strong>Buscar ajuste...</strong> procura em todas as abas, inclusive nas opções de dentro dos cards. Aceita várias palavras em qualquer ordem e tolera abreviações e pequenos erros de digitação. Não é preciso clicar no campo: comece a digitar com a página aberta.</p><h2 id="gerenciadores-de-dados" tabindex="-1">Gerenciadores de dados <a class="header-anchor" href="#gerenciadores-de-dados" aria-label="Permalink to &quot;Gerenciadores de dados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gerenciador</th><th>Funcionalidade</th></tr></thead><tbody><tr><td>Gerenciar contatos salvos</td><td><a href="./../funcionalidades/eproc-historico-emails">Histórico de e-mails avançado</a></td></tr><tr><td>Gerenciar modelos de mensagem</td><td><a href="./../funcionalidades/eproc-modelos-mensagem">Modelos de mensagem</a></td></tr><tr><td>Gerenciar destaques e combinações de cores</td><td><a href="./../funcionalidades/eproc-destaques-trecho">Destaques de trecho</a></td></tr><tr><td>Gerenciar colunas excluídas e processos monitorados</td><td><a href="./../funcionalidades/eproc-monitor-relatorio">Monitor de Relatórios</a></td></tr><tr><td>Escolher perfil favorito</td><td><a href="./../funcionalidades/eproc-perfil-favorito-login">Perfil favorito no login</a></td></tr><tr><td>Gerenciar avisos rotineiros e ocultos</td><td><a href="./../funcionalidades/eproc-alertas-inline">Alertas menos intrusivos</a></td></tr><tr><td>Gerenciar rótulos aprendidos</td><td><a href="./../funcionalidades/rupe-cpha-preenchimento">Preenchimento automático de CPHA</a></td></tr></tbody></table><p>Nos gerenciadores, Esc fecha a janela aberta por cima, sem fechar as de baixo.</p>',16)]))}const h=e(d,[["render",i]]);export{m as __pageData,h as default};
